# Restock alert: find drugs below 50 strips
stock = {"Paracetamol": 120, "Cetirizine": 45, "ORS": 20}
low = []
for drug, qty in stock.items():
    if qty < 50:
        low.append(drug)
low.sort()
print("Reorder:", low)
print("Items to reorder:", len(low))

